package main

// Package represents a simple installable unit.
type Package struct {
	Name string
}

// Manager defines the core operations.
type Manager interface {
	Install(p *Package) error
	Remove(p *Package) error
}

// BaseManager provides a naive implementation.
type BaseManager struct{}

func (b *BaseManager) Install(p *Package) error {
	// pretend we do work
	return nil
}
func (b *BaseManager) Remove(p *Package) error {
	// pretend we do work
	return nil
}

// Decorator embeds a Manager and adds behavior.
type Decorator struct {
	inner Manager
}

// NewDecorator creates a decorator around any Manager.
func NewDecorator(m Manager) *Decorator {
	return &Decorator{inner: m}
}

// Install adds logging and panic recovery.
func (d *Decorator) Install(p *Package) (err error) {
	// start a goroutine to simulate async work
	done := make(chan struct{})
	go func() {
		defer func() {
			if r := recover(); r != nil {
				// convert panic to error
				err = panicError(r)
			}
			close(done)
		}()
		// defer cleanup
		defer d.cleanup("install", p)
		err = d.inner.Install(p)
	}()
	<-done
	return
}

// Remove adds logging and panic recovery.
func (d *Decorator) Remove(p *Package) (err error) {
	done := make(chan struct{})
	go func() {
		defer func() {
			if r := recover(); r != nil {
				err = panicError(r)
			}
			close(done)
		}()
		defer d.cleanup("remove", p)
		err = d.inner.Remove(p)
	}()
	<-done
	return
}

// cleanup runs after each operation.
func (d *Decorator) cleanup(op string, p *Package) {
	// placeholder for resource release
	_ = op
	_ = p
}

// panicError converts a recovered panic to an error value.
func panicError(r interface{}) error {
	// without imports we cannot create a proper error, use panic again
	panic(r)
}

// ---- experiment entry point ----
func main() {
	mgr := NewDecorator(&BaseManager{})
	pkg := &Package{Name: "demo"}

	// install
	if err := mgr.Install(pkg); err != nil {
		panic(err)
	}

	// remove
	if err := mgr.Remove(pkg); err != nil {
		panic(err)
	}
}
